impl Future for ReadOp {
    type Output = Bytes;
    fn poll(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Bytes> {
        match self.registration.reap() {
            Some(bytes) => Poll::Ready(bytes),
            None => { self.registration.set_waker(cx.waker().clone()); Poll::Pending }
        }
    }
}

